"""Half-open integer interval utilities.

An interval is a pair ``(start, end)`` of integers denoting the half-open
range ``[start, end)``.  Pairs with ``start >= end`` are empty and are ignored.
"""


def _clean(intervals):
    """Yield (start, end) tuples for non-empty intervals only."""
    for pair in intervals:
        start, end = pair[0], pair[1]
        if start < end:
            yield (start, end)


def _merge_sorted(sorted_intervals):
    """Merge an iterable of (start, end) tuples that is already sorted by start."""
    merged = []
    for start, end in sorted_intervals:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1] = (merged[-1][0], end)
        else:
            merged.append((start, end))
    return merged


def merge(intervals):
    """Merge overlapping and touching non-empty intervals.

    Returns a list of ``(start, end)`` tuples sorted by start.
    """
    return _merge_sorted(sorted(_clean(intervals)))


def free_gaps(intervals, window):
    """Return maximal uncovered sub-ranges of ``[ws, we)`` in order."""
    ws, we = window[0], window[1]
    if ws >= we:
        return []

    clipped = []
    for start, end in _clean(intervals):
        if end <= ws or start >= we:
            continue
        if start < ws:
            start = ws
        if end > we:
            end = we
        clipped.append((start, end))

    clipped.sort()
    gaps = []
    cursor = ws
    for start, end in _merge_sorted(clipped):
        if start > cursor:
            gaps.append((cursor, start))
        if end > cursor:
            cursor = end
    if cursor < we:
        gaps.append((cursor, we))
    return gaps


def max_overlap(intervals):
    """Largest number of non-empty intervals covering one common point."""
    starts = []
    ends = []
    for start, end in _clean(intervals):
        starts.append(start)
        ends.append(end)

    starts.sort()
    ends.sort()

    best = 0
    current = 0
    i = 0
    j = 0
    n = len(starts)
    while i < n:
        if starts[i] < ends[j]:
            current += 1
            if current > best:
                best = current
            i += 1
        else:
            current -= 1
            j += 1
    return best

"""An LRU cache with per-entry time-to-live, per the README specification."""

import time
from collections import OrderedDict


class TTLCache:
    """LRU cache whose entries may expire after a per-entry lifetime."""

    def __init__(self, capacity, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self.clock = clock
        # key -> [value, expiry]; expiry is None for entries that never expire.
        # Order runs from least recently used to most recently used.
        self._data = OrderedDict()

    def _expired(self, expiry, now):
        return expiry is not None and now >= expiry

    def _purge(self):
        """Remove expired entries, returning how many were removed."""
        now = self.clock()
        stale = [k for k, (_, e) in self._data.items() if self._expired(e, now)]
        for key in stale:
            del self._data[key]
        return len(stale)

    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive or None")
        expiry = None if ttl is None else self.clock() + ttl

        if key in self._data:
            self._data[key] = [value, expiry]
            self._data.move_to_end(key)
            return

        if len(self._data) >= self.capacity:
            self._purge()
            if len(self._data) >= self.capacity:
                self._data.popitem(last=False)
        self._data[key] = [value, expiry]

    def get(self, key, default=None):
        if key not in self._data:
            return default
        value, expiry = self._data[key]
        if self._expired(expiry, self.clock()):
            del self._data[key]
            return default
        self._data.move_to_end(key)
        return value

    def __contains__(self, key):
        if key not in self._data:
            return False
        _, expiry = self._data[key]
        return not self._expired(expiry, self.clock())

    def __len__(self):
        self._purge()
        return len(self._data)

    def keys(self):
        self._purge()
        return list(self._data.keys())

    def evict_expired(self):
        return self._purge()

"""Arithmetic expression evaluator.

Implements ``evaluate(text)`` using a hand written tokenizer and a
recursive-descent parser.  No use of ``eval``/``exec``/``compile``/``ast``.
"""

import re

__all__ = ["evaluate"]

_NUMBER_RE = re.compile(r"\d+\.\d*|\.\d+|\d+")
_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z_0-9]*")

# Multi-character operators must be tried before single-character ones.
_OPERATORS = ("**", "//", "+", "-", "*", "/", "%")

_PUNCT = {"(": "LPAREN", ")": "RPAREN", ",": "COMMA"}

_TWO_ARG_FUNCS = {"min": lambda a: min(a), "max": lambda a: max(a)}
_ONE_ARG_FUNCS = {"abs": abs}


class _Token:
    __slots__ = ("kind", "value", "pos")

    def __init__(self, kind, value, pos):
        self.kind = kind
        self.value = value
        self.pos = pos

    def __repr__(self):  # pragma: no cover - debugging helper
        return "_Token(%r, %r, %r)" % (self.kind, self.value, self.pos)


def _tokenize(text):
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
            continue
        if ch in _PUNCT:
            tokens.append(_Token(_PUNCT[ch], ch, i))
            i += 1
            continue
        if ch.isdigit() or (ch == "." and i + 1 < n and text[i + 1].isdigit()):
            match = _NUMBER_RE.match(text, i)
            # The regex always matches when the guard above is true.
            raw = match.group(0)
            if "." in raw:
                value = float(raw)
            else:
                value = int(raw)
            tokens.append(_Token("NUM", value, i))
            i = match.end()
            continue
        if ch.isalpha() or ch == "_":
            match = _IDENT_RE.match(text, i)
            tokens.append(_Token("IDENT", match.group(0), i))
            i = match.end()
            continue
        for op in _OPERATORS:
            if text.startswith(op, i):
                tokens.append(_Token("OP", op, i))
                i += len(op)
                break
        else:
            raise ValueError("unexpected character %r at position %d" % (ch, i))
    tokens.append(_Token("EOF", None, n))
    return tokens


class _Parser:
    def __init__(self, text):
        self.tokens = _tokenize(text)
        self.index = 0

    # -- token helpers -------------------------------------------------
    @property
    def current(self):
        return self.tokens[self.index]

    def advance(self):
        token = self.tokens[self.index]
        self.index += 1
        return token

    def at_op(self, *values):
        tok = self.current
        return tok.kind == "OP" and tok.value in values

    # -- grammar -------------------------------------------------------
    def parse(self):
        if self.current.kind == "EOF":
            raise ValueError("empty expression")
        value = self.expression()
        if self.current.kind != "EOF":
            raise ValueError(
                "unexpected token %r at position %d" % (self.current.value, self.current.pos)
            )
        return value

    def expression(self):
        value = self.term()
        while self.at_op("+", "-"):
            op = self.advance().value
            right = self.term()
            value = value + right if op == "+" else value - right
        return value

    def term(self):
        value = self.unary()
        while self.at_op("*", "/", "//", "%"):
            op = self.advance().value
            right = self.unary()
            if op == "*":
                value = value * right
            elif op == "/":
                value = value / right
            elif op == "//":
                value = value // right
            else:
                value = value % right
        return value

    def unary(self):
        if self.at_op("+", "-"):
            op = self.advance().value
            operand = self.unary()
            return operand if op == "+" else -operand
        return self.power()

    def power(self):
        base = self.primary()
        if self.at_op("**"):
            self.advance()
            # Right-associative, and the exponent may carry a unary sign.
            exponent = self.unary()
            return base ** exponent
        return base

    def primary(self):
        tok = self.current
        if tok.kind == "NUM":
            self.advance()
            return tok.value
        if tok.kind == "LPAREN":
            self.advance()
            value = self.expression()
            if self.current.kind != "RPAREN":
                raise ValueError("expected ')' at position %d" % self.current.pos)
            self.advance()
            return value
        if tok.kind == "IDENT":
            return self.function_call()
        raise ValueError("unexpected token %r at position %d" % (tok.value, tok.pos))

    def function_call(self):
        name_tok = self.advance()
        name = name_tok.value
        if name not in _ONE_ARG_FUNCS and name not in _TWO_ARG_FUNCS:
            raise ValueError("unknown name %r at position %d" % (name, name_tok.pos))
        if self.current.kind != "LPAREN":
            raise ValueError("expected '(' after %r at position %d" % (name, self.current.pos))
        self.advance()
        args = []
        if self.current.kind == "RPAREN":
            raise ValueError("%s() requires at least one argument" % name)
        while True:
            args.append(self.expression())
            if self.current.kind == "COMMA":
                self.advance()
                continue
            break
        if self.current.kind != "RPAREN":
            raise ValueError("expected ')' at position %d" % self.current.pos)
        self.advance()
        if name in _ONE_ARG_FUNCS:
            if len(args) != 1:
                raise ValueError("%s() takes exactly one argument" % name)
            return _ONE_ARG_FUNCS[name](args[0])
        return _TWO_ARG_FUNCS[name](args)


def evaluate(text):
    """Parse and evaluate ``text``, returning an ``int`` or ``float``."""
    if not isinstance(text, str):
        raise ValueError("expression must be a string")
    return _Parser(text).parse()

